import base64, os
S = os.path.dirname(os.path.abspath(__file__))
IMG = os.path.join(S, '..', 'references', 'memoryos', 'analogs')
CSS = open(os.path.join(S, 'report-style.css'), encoding='utf-8').read()
OUT = os.path.join(S, 'memoryos-analogs-v2-2026-11-03.html')

def fig(name, cap):
    b = base64.b64encode(open(os.path.join(IMG, name), 'rb').read()).decode()
    return f'<figure><img src="data:image/jpeg;base64,{b}" alt="{cap}"><figcaption>{cap}</figcaption></figure>'

def gallery(items): return '<div class="gallery">' + ''.join(fig(n, c) for n, c in items) + '</div>'
def tag(k): return {'d': '<span class="tag ok">Видно в данных</span>', 'p': '<span class="tag warn">Предположение</span>', 'n': '<span class="tag crit">Не знаем</span>'}[k]
D, P, N = tag('d'), tag('p'), tag('n')
def src(t): return f'<p class="small muted">Источники: {t}</p>'
def table(head, rows):
    h = ''.join(f'<th>{x}</th>' for x in head)
    b = ''.join('<tr>' + ''.join(f'<td>{x}</td>' for x in r) + '</tr>' for r in rows)
    return f'<div class="tw"><table><thead><tr>{h}</tr></thead><tbody>{b}</tbody></table></div>'
def flow(steps): return '<div class="flow">' + ''.join(f'<div class="step"><b>{a}</b>{b}</div>' for a, b in steps) + '</div>'

H = []; a = H.append
